from datetime import date, timedelta


class Library:
    def __init__(self, loan_days: int = 14, daily_fine: float = 0.5) -> None:
        self.loan_days = loan_days
        self.daily_fine = daily_fine
        self.books = {}  # book_id -> {'borrowed_by': user, 'borrow_date': date} or None if available
        self.fines = {}  # user -> total unpaid fine amount

    def add_book(self, book_id: str) -> None:
        self.books[book_id] = None

    def borrow(self, user: str, book_id: str, day: date) -> None:
        if book_id not in self.books:
            raise ValueError(f"Book {book_id} does not exist")
        if self.books[book_id] is not None:
            raise ValueError(f"Book {book_id} is already borrowed")
        self.books[book_id] = {'borrowed_by': user, 'borrow_date': day}

    def return_book(self, user: str, book_id: str, day: date) -> float:
        if book_id not in self.books:
            raise ValueError(f"Book {book_id} does not exist")
        if self.books[book_id] is None:
            raise ValueError(f"Book {book_id} is not borrowed")
        if self.books[book_id]['borrowed_by'] != user:
            raise ValueError(f"Book {book_id} was not borrowed by {user}")

        borrow_record = self.books[book_id]
        due_date = borrow_record['borrow_date'] + timedelta(days=self.loan_days)

        # Calculate delay days (excluding weekends)
        delay_days = 0
        current_date = due_date + timedelta(days=1)
        while current_date <= day:
            # Only count weekdays (Monday=0, Sunday=6)
            if current_date.weekday() < 5:  # Monday to Friday
                delay_days += 1
            current_date += timedelta(days=1)

        fine = delay_days * self.daily_fine

        # Update fines for the user
        if user not in self.fines:
            self.fines[user] = 0.0
        self.fines[user] += fine

        # Mark book as returned
        self.books[book_id] = None

        return fine

    def unpaid_fines(self, user: str) -> float:
        return self.fines.get(user, 0.0)

    def pay(self, user: str) -> None:
        if user in self.fines:
            self.fines[user] = 0.0
